        DistinctValue *v=&page->values[index-page->offset]; bool partial=false,checked=value_checked(a,v->key,&partial);
        bool click=ui_popup_row(u,item,"",CARBON_COUNT,allow); filter_checkbox(u,item,checked,partial);
