    ui_label(u,"Condition",box(r.title.x+10*s,cy+7*s,65*s,25*s),10.5f,UI_MUTED,false,UI_REGULAR);
    bool blocked=u->pointer_blocked; if (!allow) u->pointer_blocked=true;
