                            if (!total_column && active && a->matrix_cells_active && o->row+row+2>=r0 && o->row+row+2<=r1 && o->col+c>=c0 && o->col+c<=c1) clipped_fill(value,clip,UI_TINT);
                            matrix_cell_edges(value,clip,s);
