        if (a->analysis.sort_count!=2 || a->page.columns[1].sort_priority!=1 || !a->page.columns[2].sort_descending) goto failed;
        history(a,false); break;
    case 5:
        if (a->analysis.sort_column || a->page.cells[0].number!=7) goto failed;
