/* Compare visible sticky paint, not only the stationary widget rectangles. */
static bool smoke_same_pipeline_header(App *a,const char *baseline) {
    Image before=LoadImage(baseline),after=LoadImageFromScreen();
    Rectangle header=a->pipeline_layout.header; Vector2 density=a->ui.render_scale;
    Rectangle pixels={roundf(header.x*density.x),roundf(header.y*density.y),roundf(header.width*density.x),roundf(header.height*density.y)};
    bool ok=before.data && after.data && before.width==after.width && before.height==after.height &&
        pixels.width>0 && pixels.height>0 && pixels.x>=0 && pixels.y>=0 &&
        pixels.x+pixels.width<=before.width && pixels.y+pixels.height<=before.height;
    if (ok) {
        ImageCrop(&before,pixels); ImageCrop(&after,pixels);
        ImageFormat(&before,PIXELFORMAT_UNCOMPRESSED_R8G8B8A8); ImageFormat(&after,PIXELFORMAT_UNCOMPRESSED_R8G8B8A8);
        size_t count=(size_t)before.width*(size_t)before.height,ink=0;
        const unsigned char *rgba=before.data;
        for (size_t i=0;i<count;i++) if (rgba[i*4]<150 && rgba[i*4+1]<150 && rgba[i*4+2]<150) ink++;
        ok=ink>40 && !memcmp(before.data,after.data,count*4);
        if (!ok) fprintf(stderr,"Sticky header paint changed: %zu dark baseline pixels, %dx%d ROI\n",ink,before.width,before.height);
    }
    UnloadImage(before); UnloadImage(after); return ok;
}
static bool smoke_legacy_format_book(const char *path,const char *source,char **error) {
    Workbook book; workbook_init(&book); Analysis input={.kind=SOURCE_PARQUET,.path=dx_absolute_path(source)};
    bool ok=input.path && workbook_add(&book,"Legacy transactions",&input,error); analysis_free(&input);
    if (ok) {
        Worksheet *sheet=book.sheets; CellFormat value=format_default(); value.color=3;
        ok=format_apply(&sheet->formats,(FormatRange){0,DX_SHEET_ROWS-1,4,4},FORMAT_COLOR,value,error);
        value.flags=FORMAT_BOLD;
        if (ok) ok=format_apply(&sheet->formats,(FormatRange){0,11,4,4},FORMAT_BOLD,value,error);
        value.color=2;
        if (ok) ok=format_apply(&sheet->formats,(FormatRange){20,700,4,8},FORMAT_COLOR,value,error) &&
            cells_set(&sheet->cells,700,0,"Below the source",error) && cells_set(&sheet->cells,700,8,"Legacy note",error);
        if (ok) ok=workbook_save(&book,path,error);
    }
    workbook_free(&book); return ok;
}
static bool smoke_legacy_result_formats(App *a,bool result,bool record) {
    if (a->page.total!=600 || a->page.column_count!=5 || format_at(&active_sheet(a)->formats,700,8).color!=2) return false;
    for (size_t i=0;i<a->page.row_count;i++) {
        uint64_t row=a->page.offset+i,id=0; if (!page_record_id(&a->page,row,&id)) return false;
        CellFormat value=imported_cell_format(a,row,4);
        unsigned flags=(result && row<12 ? FORMAT_BOLD : 0) | (record && id==21 ? FORMAT_BOLD : 0);
        if (value.flags!=flags || value.color!=(result && row>=20 ? 2 : 3) || imported_cell_format(a,row,3).flags) return false;
    }
    return true;
}
/* Real retained Format history drives admission; never forge meter totals or
   Worker reservations. Only the active sheet's Redo is released by the edit. */
#define SMOKE_BUDGET_SHEETS 10
static bool smoke_budget_book(const char *path,const char *source,char **error) {
    if (!smoke_legacy_format_book(path,source,error)) return false;
    Workbook book; workbook_init(&book); bool ok=workbook_load(&book,path,error);
    for (size_t i=1;ok && i<SMOKE_BUDGET_SHEETS;i++) {
        char name[32]; snprintf(name,sizeof(name),"History padding %zu",i);
        Analysis manual={0}; ok=workbook_add(&book,name,&manual,error);
    }
    book.active=0; if (ok) ok=workbook_save(&book,path,error);
    workbook_free(&book); return ok;
}
static bool smoke_budget_pressure(App *a,char **error) {
    if (a->book.count!=SMOKE_BUDGET_SHEETS || a->book.active || !source_format_origin_valid(a)) return false;
    a->modal=MODAL_GUIDE;
    for (size_t sheet=0;sheet<a->book.count;sheet++) {
        Worksheet *s=a->book.sheets+sheet; size_t patches=s->formats.count;
        for (size_t i=0;i<DX_FORMAT_PATCHES-patches;i++) {
            CellFormat value=format_default(); value.color=1;
            if (!format_apply(&s->formats,(FormatRange){1000+2*i,1000+2*i,8,8},FORMAT_COLOR,value,error)) return false;
            worksheet_record(s,EDIT_FORMAT);
        }
        for (size_t i=0;i<DX_FORMAT_HISTORY;i++) {
            CellFormat value=format_default(); value.color=(unsigned char)(2+i%2);
            if (!format_apply(&s->formats,(FormatRange){1000,1000,8,8},FORMAT_COLOR,value,error)) return false;
            worksheet_record(s,EDIT_FORMAT);
        }
        if (s->formats.count!=DX_FORMAT_PATCHES || s->formats.undo_count!=DX_FORMAT_HISTORY || s->formats.redo_count) return false;
    }
    for (size_t i=0;i<DX_FORMAT_HISTORY;i++) history(a,false);
    Worksheet *s=active_sheet(a); WorkbookFormatUsage usage={0};
    if (workbook_format_usage(&a->book,NULL,0,&usage)!=FORMAT_BUDGET_OK ||
        usage.current!=SMOKE_BUDGET_SHEETS*DX_FORMAT_PATCHES*sizeof(FormatPatch) ||
        usage.retained!=usage.current*(DX_FORMAT_HISTORY+1) ||
        s->formats.undo_count || s->formats.redo_count!=DX_FORMAT_HISTORY ||
        s->undo_actions_count || s->redo_actions_count!=DX_FORMAT_HISTORY || !source_format_origin_valid(a)) return false;
    a->book.dirty=true; grid_select_cell(&a->grid,0,0,false);
    a->grid.top=a->last_top=0; a->viewport_changed=dx_millis()-1000; a->modal=MODAL_NONE; return true;
}
